package com.confApi.plantao;
import com.confApi.authv2.V2;import com.fasterxml.jackson.databind.JsonNode;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
/** Regression for the former encrypted/plaintext-code leak, now replaced by opaque challenges. */
class PlantaoTokenEncryptedResponseTest {
 static class Service extends PlantaoTokenService {String path;JsonNode sent;boolean fail,wrong;String id=UUID.randomUUID().toString();protected JsonNode call(String path,Object body){this.path=path;sent=V2.JSON.valueToTree(body);if(fail)throw new V2.Failure(503);if(path.endsWith("validar"))return V2.JSON.valueToTree(Map.of("authenticated",!wrong,"challengeId",id));return V2.JSON.valueToTree(Map.of("challengeId",id,"reference",sent.path("reference").asText(),"purpose",wrong?"PORTAL_LOGIN":"PLANTAO","state","PENDENTE","expiresAt","2030-01-01T00:00:00Z","token","must-never-be-returned"));}}
 PlantaoTokenRequest request(String channel,String ref){return new PlantaoTokenRequest("alice",channel,"untrusted-phone",ref);}
 @Test void appReturnsOnlyOpaqueChallenge(){var s=new Service();var r=s.gerar(request("APP",UUID.randomUUID().toString()),"Bearer synthetic");assertTrue(r.success());assertNull(r.token());assertEquals(s.id,r.challengeId());assertEquals("/internal/v2/operacoes/desafios",s.path);assertEquals("PLANTAO",s.sent.path("purpose").asText());}
 @Test void emailDoesNotForwardCallerSuppliedDestination(){var s=new Service();assertTrue(s.gerar(request("EMAIL",UUID.randomUUID().toString()),"").success());assertFalse(s.sent.has("celular"));assertFalse(s.sent.has("recipient"));assertEquals("EMAIL",s.sent.path("channel").asText());}
 @Test void rejectsWrongPurposeResponse(){var s=new Service();s.wrong=true;assertFalse(s.gerar(request("APP",UUID.randomUUID().toString()),"").success());}
 @Test void missingReferenceCannotTriggerIssuance(){var s=new Service();assertFalse(s.gerar(request("APP",null),"").success());assertNull(s.path);}
 @Test void unknownChannelCannotTriggerIssuance(){var s=new Service();assertFalse(s.gerar(request("SMS",UUID.randomUUID().toString()),"").success());assertNull(s.path);}
 @Test void unavailableServiceDoesNotFallBack(){var s=new Service();s.fail=true;assertFalse(s.gerar(request("APP",UUID.randomUUID().toString()),"").success());}
 @Test void validationUsesExactChallengeContextAndFourDigitString(){var s=new Service();String ref=UUID.randomUUID().toString();assertTrue(s.validar(new PlantaoTokenValidationRequest("alice","0123","APP",s.id,ref)).success());assertEquals("0123",s.sent.path("code").asText());assertEquals(ref,s.sent.path("reference").asText());assertEquals("PLANTAO",s.sent.path("purpose").asText());assertFalse(s.path.contains("0123"));}
 @Test void rejectsSixDigitAndEncryptedValues(){for(String code:List.of("123456","encryption.v1.fake","123","12345","1234 ")){var s=new Service();assertFalse(s.validar(new PlantaoTokenValidationRequest("alice",code,"APP",s.id,UUID.randomUUID().toString())).success());assertNull(s.path);}}
 @Test void missingChallengeCannotPerformGlobalCodeSearch(){var s=new Service();assertFalse(s.validar(new PlantaoTokenValidationRequest("alice","1234","APP",null,UUID.randomUUID().toString())).success());assertNull(s.path);}
 @Test void failedValidationDoesNotGrantAccess(){var s=new Service();s.wrong=true;assertFalse(s.validar(new PlantaoTokenValidationRequest("alice","1234","APP",s.id,UUID.randomUUID().toString())).success());}
 @Test void unavailableValidationDoesNotGrantAccess(){var s=new Service();s.fail=true;assertFalse(s.validar(new PlantaoTokenValidationRequest("alice","1234","APP",s.id,UUID.randomUUID().toString())).success());}
}
